class Solution {
public:
    vector<bool> findAnswer(vector<int>& parent, string s) {
        int n = parent.size();
        vector<vector<int>> ch(n);
        for (int i = 1; i < n; i++) ch[parent[i]].push_back(i);
        vector<string> strs(n);
        function<string(int)> dfs = [&](int x) -> string {
            string r;
            for (int y : ch[x]) r += dfs(y);
            r += s[x];
            strs[x] = r;
            return r;
        };
        dfs(0);
        vector<bool> ans(n);
        for (int i = 0; i < n; i++) {
            string t = strs[i];
            reverse(t.begin(), t.end());
            ans[i] = t == strs[i];
        }
        return ans;
    }
};

