class Solution {
    String[] strs;
    List<Integer>[] ch;
    String s;
    private String dfs(int x) {
        StringBuilder sb = new StringBuilder();
        for (int y : ch[x]) sb.append(dfs(y));
        sb.append(s.charAt(x));
        strs[x] = sb.toString();
        return strs[x];
    }
    public boolean[] findAnswer(int[] parent, String s) {
        int n = parent.length;
        this.s = s;
        strs = new String[n];
        ch = new List[n];
        for (int i = 0; i < n; i++) ch[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) ch[parent[i]].add(i);
        dfs(0);
        boolean[] ans = new boolean[n];
        for (int i = 0; i < n; i++) {
            String t = new StringBuilder(strs[i]).reverse().toString();
            ans[i] = t.equals(strs[i]);
        }
        return ans;
    }
}

