class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        ch = [[] for _ in range(n)]
        for i in range(1, n):
            ch[parent[i]].append(i)
        start = [0] * n
        end = [0] * n
        cursor = 0
        st = [(0, False)]
        while st:
            x, done = st.pop()
            if done:
                end[x] = cursor
                cursor += 1
                continue
            start[x] = cursor
            st.append((x, True))
            for y in ch[x]:
                st.append((y, False))
        t = '#' + '#'.join(s) + '#'
        m = len(t)
        p = [0] * m
        c = r = 0
        for i in range(m):
            if i < r:
                p[i] = min(r - i, p[2 * c - i])
            while i - p[i] - 1 >= 0 and i + p[i] + 1 < m and t[i - p[i] - 1] == t[i + p[i] + 1]:
                p[i] += 1
            if i + p[i] > r:
                c, r = i, i + p[i]
        return [p[start[i] + end[i] + 1] >= end[i] - start[i] + 1 for i in range(n)]

