class Solution {
public:
    vector<bool> findAnswer(vector<int>& parent, string s) {
        int n = parent.size();
        vector<vector<int>> ch(n);
        for (int i = 1; i < n; i++) ch[parent[i]].push_back(i);
        vector<int> start(n), end(n);
        int cursor = 0;
        function<void(int)> dfs = [&](int x) {
            start[x] = cursor;
            for (int y : ch[x]) dfs(y);
            end[x] = cursor++;
        };
        dfs(0);
        string t;
        t.reserve(2 * n + 1);
        for (char c : s) { t += '#'; t += c; }
        t += '#';
        int m = t.size();
        vector<int> p(m);
        int cc = 0, rr = 0;
        for (int i = 0; i < m; i++) {
            if (i < rr) p[i] = min(rr - i, p[2 * cc - i]);
            while (i - p[i] - 1 >= 0 && i + p[i] + 1 < m && t[i - p[i] - 1] == t[i + p[i] + 1]) p[i]++;
            if (i + p[i] > rr) { cc = i; rr = i + p[i]; }
        }
        vector<bool> ans(n);
        for (int i = 0; i < n; i++)
            ans[i] = p[start[i] + end[i] + 1] >= end[i] - start[i] + 1;
        return ans;
    }
};

