class Solution {
    List<Integer>[] ch;
    int[] start, end;
    int cursor;
    String s;
    private void dfs(int x) {
        start[x] = cursor;
        for (int y : ch[x]) dfs(y);
        end[x] = cursor++;
    }
    public boolean[] findAnswer(int[] parent, String s) {
        int n = parent.length;
        this.s = s;
        ch = new List[n];
        for (int i = 0; i < n; i++) ch[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) ch[parent[i]].add(i);
        start = new int[n]; end = new int[n]; cursor = 0;
        dfs(0);
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) { sb.append('#').append(c); }
        sb.append('#');
        String t = sb.toString();
        int m = t.length();
        int[] p = new int[m];
        int cc = 0, rr = 0;
        for (int i = 0; i < m; i++) {
            if (i < rr) p[i] = Math.min(rr - i, p[2 * cc - i]);
            while (i - p[i] - 1 >= 0 && i + p[i] + 1 < m && t.charAt(i - p[i] - 1) == t.charAt(i + p[i] + 1)) p[i]++;
            if (i + p[i] > rr) { cc = i; rr = i + p[i]; }
        }
        boolean[] ans = new boolean[n];
        for (int i = 0; i < n; i++)
            ans[i] = p[start[i] + end[i] + 1] >= end[i] - start[i] + 1;
        return ans;
    }
}

